import { randomUUID } from 'node:crypto';

import type { ImageMimeType } from '@app/shared';

/*
 * Object keys are generated by the server (F-21, B-05): a random UUID v4 plus the extension of the **detected** type.
 * The client filename never reaches a key. The DB stores only the original's key (B-35, DATA-MODEL CHECK
 * `images_object_key_format`); the preview key is derived from it (ADR 0018).
 */

/** Lowercase UUID v4, as `crypto.randomUUID()` produces it. */
const UUID_V4 = '[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}';

export const ORIGINALS_PREFIX = 'images';
export const PREVIEWS_PREFIX = 'previews';

export const EXTENSION_BY_TYPE = {
  'image/jpeg': 'jpg',
  'image/png': 'png',
  'image/webp': 'webp',
  'image/gif': 'gif',
} as const satisfies Record<ImageMimeType, string>;

export type ImageExtension = (typeof EXTENSION_BY_TYPE)[ImageMimeType];

/** `jpg|png|webp|gif`: derived, so the patterns below accept exactly the extensions of EXTENSION_BY_TYPE. */
const EXTENSIONS = Object.values(EXTENSION_BY_TYPE).join('|');

/** File name of an original as the media route receives it (`/api/media/images/:file`). */
export const MEDIA_FILE_PATTERN = new RegExp(`^${UUID_V4}\\.(?:${EXTENSIONS})$`);
/** File name of a preview (`/api/media/previews/:file`). */
export const PREVIEW_FILE_PATTERN = new RegExp(`^${UUID_V4}\\.webp$`);
/** Key of an original: the same pattern as the DB CHECK constraint. */
export const MEDIA_KEY_PATTERN = new RegExp(`^${ORIGINALS_PREFIX}/(${UUID_V4})\\.(${EXTENSIONS})$`);
/** Key of a preview. */
export const PREVIEW_KEY_PATTERN = new RegExp(`^${PREVIEWS_PREFIX}/${UUID_V4}\\.webp$`);

export interface ParsedObjectKey {
  uuid: string;
  extension: ImageExtension;
}

/** `images/<uuid>.<ext>` → its parts, or `undefined` when the key does not match MEDIA_KEY_PATTERN. */
export function parseObjectKey(objectKey: string): ParsedObjectKey | undefined {
  const match = MEDIA_KEY_PATTERN.exec(objectKey);
  const uuid = match?.[1];
  const extension = match?.[2];
  if (uuid === undefined || extension === undefined) return undefined;
  // The pattern's alternation is built from the values of EXTENSION_BY_TYPE.
  return { uuid, extension: extension as ImageExtension };
}

/**
 * A fresh key for a detected type. `randomUUID` is synchronous and cannot fail, so there is no promise that could hang
 * a request (B-20). `newUuid` is a seam for tests only.
 */
export function newObjectKey(mimeType: ImageMimeType, newUuid: () => string = randomUUID): string {
  return `${ORIGINALS_PREFIX}/${newUuid()}.${EXTENSION_BY_TYPE[mimeType]}`;
}

/** `images/<uuid>.<ext>` → `previews/<uuid>.webp`. Throws for a key that is not an original's key. */
export function previewKeyOf(objectKey: string): string {
  const parsed = parseObjectKey(objectKey);
  if (parsed === undefined) throw new Error(`Not an image object key: ${JSON.stringify(objectKey)}`);
  return `${PREVIEWS_PREFIX}/${parsed.uuid}.webp`;
}
